// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "Dominoes"

let n = 24; // grid size
let dominoes, freeSpots;
const N_FRAMES = 15; // how long a domino animation lasts

function setup() {
	createCanvas(500, 500);
	pixelDensity(2);
	noStroke();

	createComposition();
	startMovingOne(0);
}

function draw() {
	background("#0a0a0a");

	let margin = 50;
	let s = (width-2*margin)/n;
	let gap = 1.5;
	let dpth = 5;

	for (let domino of dominoes) {
		let {i, j, si, sj, col, moving, tStart, target} = domino;
		let x, y;
		fill(col);

		if (moving) {
			let t = easeInOutCubic((frameCount-tStart)/N_FRAMES);
			let x0 = margin + i*s;
			let y0 = margin + j*s;
			let x1 = margin + target.i*s;
			let y1 = margin + target.j*s;
			x = x0*(1-t) + x1*t;
			y = y0*(1-t) + y1*t;
			if (frameCount == tStart + N_FRAMES) {
				endMovement(domino);
			}
		} else {
			x = margin + i*s;
			y = margin + j*s;
		}

		let w = si*s, h = sj*s;

		rect(x+gap/2, y+gap/2, w-gap, h-gap, s/5);
	}

	startMovingOne(frameCount);
}

// bad domino tiling: add dominoes in random positions until you can't
function createComposition() {
	let positions = [];
	freeSpots = [];
	for (let i = 0; i < n; i++) {
		freeSpots[i] = [];
		for (let j = 0; j < n; j++) {
			positions.push([i, j]);
			freeSpots[i][j] = true;
		}
	}

	shuffle(positions, true);
	dominoes = [];
	while (positions.length > 0) {
		let [iA, jA] = positions.pop();
		if (!freeSpots[iA][jA]) continue;
		let neighbors = getNeighbors(iA, jA, n, freeSpots);
		if (neighbors.length == 0) continue;
		let [iB, jB] = random(neighbors);
		let newDomino = createDomino(iA, jA, iB, jB);
		freeSpots[iA][jA] = false;
		freeSpots[iB][jB] = false;
		dominoes.push(newDomino);
	}
}

function getNeighbors(i, j, n, freeSpots) {
	let neighbors = [];
	if (i > 0 && freeSpots[i-1][j]) neighbors.push([i-1, j]);
	if (i < n - 1 && freeSpots[i+1][j]) neighbors.push([i+1, j]);
	if (j > 0 && freeSpots[i][j-1]) neighbors.push([i, j-1]);
	if (j < n - 1 && freeSpots[i][j+1]) neighbors.push([i, j+1]);
	return neighbors;
}

function createDomino(iA, jA, iB, jB) {
	let i = iA, j = jA, si = 1, sj = 1, col = random() < 1/6 ? "#f6d448" : random(["#71859d", "#fafafa"]);
	if (iA == iB) {
		if (jA < jB) {
			sj = 2;
		} else {
			j = jB;
			sj = 2;
		}
	} else if (iA < iB) {
		si = 2;
	} else {
		i = iB;
		si = 2;
	}
	return {i, j, si, sj, col};
}

// find dominoes that can move and start moving one
function startMovingOne(tStart) {
	let canMove = [];
	for (let domino of dominoes) {
		if (domino.tStart && tStart - domino.tStart < 2*N_FRAMES) {
			// domino moved recently, give it a break
			continue;
		}
		let {i, j, si, sj} = domino;
		let possibleTargets = []; // where can the domino move?
		if (si == 1) {
			// vertical domino
			if (j > 0 && freeSpots[i][j-1]) {
				possibleTargets.push({i: i, j: j-1});
			}
			if (j < n-2 && freeSpots[i][j+2]) {
				possibleTargets.push({i: i, j: j+1});
			}
		} else {
			// horizontal domino
			if (i > 0 && freeSpots[i-1][j]) {
				possibleTargets.push({i: i-1, j: j});
			}
			if (i < n-2 && freeSpots[i+2][j]) {
				possibleTargets.push({i: i+1, j: j});
			}
		}
		if (possibleTargets.length > 0) {
			canMove.push({domino: domino, target: random(possibleTargets)});
		}
	}

	if (canMove.length == 0) {
		// can't move any domino :(
		return;
	}

	let {domino, target} = random(canMove);
	domino.moving = true;
	domino.tStart = tStart;
	domino.target = target;

	// update freeSpots (remove target)
	if (domino.si == 1) {
		if (domino.j < target.j) {
			// going down
			freeSpots[domino.i][domino.j+2] = false;
		} else {
			// going up
			freeSpots[domino.i][domino.j-1] = false;
		}
	} else {
		if (domino.i < target.i) {
			// going right
			freeSpots[domino.i+2][domino.j] = false;
		} else {
			// going left
			freeSpots[domino.i-1][domino.j] = false;
		}
	}
}

function endMovement(domino) {
	domino.moving = false;

	// update freeSpots (free origin)
	if (domino.si == 1) {
		if (domino.j < domino.target.j) {
			// going down
			freeSpots[domino.i][domino.j] = true;
		} else {
			// going up
			freeSpots[domino.i][domino.j+1] = true;
		}
	} else {
		if (domino.i < domino.target.i) {
			// going right
			freeSpots[domino.i][domino.j] = true;
		} else {
			// going left
			freeSpots[domino.i+1][domino.j] = true;
		}
	}

	domino.i = domino.target.i;
	domino.j = domino.target.j;
}

// from easings.net
function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
